/**
 * @title UVM Architecture Prototype
 * @brief IEEE 1800.2 Universal Verification Methodology
 */
`include "uvm_macros.svh"
import uvm_pkg::*;

class my_test extends uvm_test;
  `uvm_component_utils(my_test)

  function new(string name = "my_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  task run_phase(uvm_phase phase);
    phase.raise_objection(this);
    `uvm_info("TEST", "Executing professional UVM environment...", UVM_LOW)
    #100;
    phase.drop_objection(this);
  endtask
endclass

class my_env extends uvm_env;
  `uvm_component_utils(my_env)
  my_agent agent;
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    agent = my_agent::type_id::create("agent", this);
  endfunction
endclass

class my_driver extends uvm_driver #(my_item);
  `uvm_component_utils(my_driver)
  virtual dut_if vif;
  task run_phase(uvm_phase phase);
    forever begin
      seq_item_port.get_next_item(req);
      vif.addr <= req.addr;
      vif.data <= req.data;
      @(posedge vif.clk);
      seq_item_port.item_done();
    end
  endtask
endclass

class my_monitor extends uvm_monitor;
  `uvm_component_utils(my_monitor)
  virtual dut_if vif;
  uvm_analysis_port #(my_item) ap;
  function void build_phase(uvm_phase phase);
    ap = new("ap", this);
  endfunction
  task run_phase(uvm_phase phase);
    forever begin
      my_item item = my_item::type_id::create("item");
      @(posedge vif.clk);
      item.addr = vif.addr;
      item.data = vif.data;
      ap.write(item);
    end
  endtask
endclass

class my_agent extends uvm_agent;
  `uvm_component_utils(my_agent)
  my_driver  drv;
  my_monitor mon;
  uvm_sequencer #(my_item) sqr;
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    mon = my_monitor::type_id::create("mon", this);
    if (is_active == UVM_ACTIVE) begin
      drv = my_driver::type_id::create("drv", this);
      sqr = uvm_sequencer#(my_item)::type_id::create("sqr", this);
    end
  endfunction
  function void connect_phase(uvm_phase phase);
    if (is_active == UVM_ACTIVE)
      drv.seq_item_port.connect(sqr.seq_item_export);
  endfunction
endclass

class my_seq extends uvm_sequence #(my_item);
  `uvm_object_utils(my_seq)
  task body();
    repeat(10) begin
      req = my_item::type_id::create("req");
      start_item(req);
      assert(req.randomize());
      finish_item(req);
    end
  endtask
endclass

class my_env extends uvm_env;
  `uvm_component_utils(my_env)
  my_agent    agent;
  my_scoreboard sb;
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    agent = my_agent::type_id::create("agent", this);
    sb = my_scoreboard::type_id::create("sb", this);
  endfunction
  function void connect_phase(uvm_phase phase);
    agent.mon.ap.connect(sb.analysis_export);
  endfunction
endclass

class base_test extends uvm_test;
  `uvm_component_utils(base_test)
  my_env env;
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = my_env::type_id::create("env", this);
  endfunction
  task run_phase(uvm_phase phase);
    my_seq seq = my_seq::type_id::create("seq");
    phase.raise_objection(this);
    seq.start(env.agent.sqr);
    phase.drop_objection(this);
  endtask
endclass

// Analysis Port (1-to-many broadcast)
uvm_analysis_port #(my_item) ap;
ap = new("ap", this);

// Analysis Implementation
class my_sb extends uvm_scoreboard;
  `uvm_component_utils(my_sb)
  uvm_analysis_imp #(my_item, my_sb) analysis_export;
  function void write(my_item item);
    // Compare expected vs actual
    `uvm_info("SB", $sformatf("Got item: %s", item.sprint()), UVM_MEDIUM)
  endfunction
endclass

class my_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(my_scoreboard)
  uvm_analysis_imp #(my_item, my_scoreboard) analysis_export;
  my_item expected_q[$];
  function void write(my_item item);
    my_item exp = expected_q.pop_front();
    if (item.data !== exp.data)
      `uvm_error("SB", $sformatf(
        "Mismatch! Expected=%0h Got=%0h", exp.data, item.data))
    else
      `uvm_info("SB", "Match!", UVM_HIGH)
  endfunction
endclass

