// UVM Phase Order:
// ─── Build-time (functions, top-down) ───
//   build_phase
//   connect_phase
//   end_of_elaboration_phase
//   start_of_simulation_phase
//
// ─── Run-time (tasks, parallel) ───
//   run_phase  ←  main phase, needs objections
//     (or sub-phases: reset, configure, main, shutdown)
//
// ─── Clean-up (functions, bottom-up) ───
//   extract_phase
//   check_phase
//   report_phase
//   final_phase

task run_phase(uvm_phase phase);
  phase.raise_objection(this, "Starting test");
  // ... stimulus ...
  phase.drop_objection(this, "Test complete");
endtask

task run_phase(uvm_phase phase);
  // MUST raise before any delay
  phase.raise_objection(this, "Starting stimulus");

  // Optional: set drain time for in-flight transactions
  uvm_objection obj = phase.get_objection();
  obj.set_drain_time(this, 100ns);

  // Run stimulus
  repeat (100) begin
    my_txn txn = my_txn::type_id::create("txn");
    start_item(txn);
    assert(txn.randomize());
    finish_item(txn);
  end

  phase.drop_objection(this, "Stimulus complete");
  // Phase waits 100ns drain time, then ends
endtask

