endclass

// Usage in a sequence:
my_ctrl_reg ctrl = reg_block.ctrl;
uvm_status_e status;
ctrl.write(status, 32'h0000_0005);   // front-door write
ctrl.read(status, rdata);              // front-door read
ctrl.mirror(status, UVM_CHECK);        // read + compare

// Fields are created inside a register's build() method:
function void build();
  // configure(parent, size, lsb_pos, access, volatile,
  //           reset, has_reset, is_rand, individually_accessible)

  status = uvm_reg_field::type_id::create("status");
  status.configure(this, 4, 0, "RO", 1, 4'h0, 1, 0, 0);

  control = uvm_reg_field::type_id::create("control");
  control.configure(this, 4, 4, "RW", 0, 4'h0, 1, 1, 0);

  reserved = uvm_reg_field::type_id::create("reserved");
  reserved.configure(this, 24, 8, "RO", 0, 24'h0, 1, 0, 0);
endfunction

// Access policies: RO, RW, RC, RS, WRC, WRS, WC, WS,
//   WSRC, WCRS, W1C, W1S, W1T, W0C, W0S, W0T, W1SRC,
//   W1CRS, W0SRC, W0CRS, WO, WOC, WOS, W1, WO1

// Inside reg_block build():
virtual function void build();
  // ... create registers ...

  default_map = create_map("default_map",
    .base_addr(0),
    .n_bytes(4),
    .endian(UVM_LITTLE_ENDIAN)
  );

  default_map.add_reg(ctrl,   'h0000, "RW");
  default_map.add_reg(status, 'h0004, "RO");
  default_map.add_reg(data,   'h0008, "RW");

