virtual reg_if vif;

virtual function void build_phase(uvm_phase phase);
  super.build_phase(phase);
  if (!uvm_config_db #(virtual reg_if)::get(this, "", "vif", vif)) begin
    `uvm_fatal(get_type_name(), "Didn't get handle to virtual interface reg_if")
  end
endfunction

virtual task run_phase(uvm_phase phase);
  reg_transaction tr;

  forever begin
    // 1. Get next item from the sequencer
    seq_item_port.get_next_item(tr);

    // 2. Drive request signals, then wait for the DUT to act on them
    @(posedge vif.clk);
    vif.wr_en <= tr.wr_en;
    vif.rd_en <= tr.rd_en;
    vif.addr  <= tr.addr;
    vif.wdata <= tr.wdata;
    @(posedge vif.clk);

    // 3. For a read, rdata isn't valid until one cycle later
    if (tr.rd_en) begin
      @(posedge vif.clk);
      tr.rdata = vif.rdata;
    end

    // 4. Tell the sequencer this item is done
    seq_item_port.item_done();
  end
endtask

virtual task run_phase(uvm_phase phase);
  reg_transaction tr;

  forever begin
    // 1. Get next item from the sequencer
    seq_item_port.get_next_item(tr);

    // 2. Drive signals to the interface
    @(posedge vif.clk);
    vif.wr_en <= tr.wr_en;
    vif.rd_en <= tr.rd_en;
    vif.addr  <= tr.addr;
    vif.wdata <= tr.wdata;

    // 3. Tell the sequencer that the driver has finished the current item
    seq_item_port.item_done();
  end
endtask

virtual task run_phase(uvm_phase phase);
  reg_transaction tr;

  forever begin
    // 1. finish_item in the sequence is unblocked here, immediately
    seq_item_port.get(tr);

    // 2. Drive signals to the interface
    @(posedge vif.clk);
    vif.wr_en <= tr.wr_en;
    vif.rd_en <= tr.rd_en;
    vif.addr  <= tr.addr;
    vif.wdata <= tr.wdata;

    // 3. Indicate the item has actually finished, separately from step 1
    seq_item_port.put(tr);
  end
endtask

@(posedge vif.clk);
vif.wr_en <= tr.wr_en;
vif.addr  <= tr.addr;
vif.wdata <= tr.wdata;
seq_item_port.item_done();

@(posedge vif.clk);
vif.wr_en <= tr.wr_en;
vif.addr  <= tr.addr;
vif.wdata <= tr.wdata;
@(posedge vif.clk);
seq_item_port.item_done();

