    forever begin
      seq_item_port.get_next_item(req);

      // Drive transaction onto the interface
      @(posedge vif.clk);
      vif.addr <= req.addr;
      vif.data <= req.data;

      seq_item_port.item_done();
    end
  endtask

  // Rest of the code (connect_phase, constructor, etc.)
