// Let's create a driver that attempts to raise/drop objection
class my_driver extends uvm_driver;
  `uvm_component_utils(my_driver)

  function new(string name="my_driver", uvm_component parent=null);
    super.new(name, parent);
  endfunction

  virtual task run_phase(uvm_phase phase);    
    uvm_objection  l_obj = phase.get_objection();
    `uvm_info(get_type_name(), $sformatf("Driver started"), UVM_MEDIUM)

    // Raise an objection in the driver just for illustration
    // Usually the driver waits until it gets an item from the 
    // sequencer and does not have to raise any objections.
    phase.raise_objection(this);
    #400;
    phase.drop_objection(this);
    l_obj.display_objections();

    `uvm_info(get_type_name(), $sformatf("Driver ended"), UVM_MEDIUM)
  endtask  
