module tb;
	initial begin
        string 			l_key;
      	uvm_event 		l_evt;
    	uvm_event 		l_evt_q [$];
    	uvm_event_pool 	l_evt_pool = uvm_event_pool::get_global_pool();

        // Add each event into the global pool
        for (byte i = 0; i < 5; i++) begin
          automatic uvm_event l_evt = new($sformatf("l_evt_%0d", i));
          l_evt_q.push_back(l_evt);
   		end

      	// Shuffle to reorder the items
      	l_evt_q.shuffle();

      	foreach (l_evt_q[i]) begin        
          l_evt_pool.add(l_evt_q[i].get_name(), l_evt_q[i]);

          if (l_evt_pool.exists(l_evt_q[i].get_name()))
            `uvm_info("tb_top", $sformatf("%s added to pool #num=%0d", l_evt_q[i].get_name(), l_evt_pool.num()), UVM_MEDIUM)
      	end

        // Get a specific handle from the global pool
      	l_evt = l_evt_pool.get_global("l_evt_3");
        `uvm_info("tb_top", $sformatf("Got item %s", l_evt.get_name()), UVM_MEDIUM)

        l_evt_pool.first(l_key);
          `uvm_info("tb_top", $sformatf("First item=%s", l_key), UVM_MEDIUM)

        while (l_evt_pool.next(l_key)) begin        
            `uvm_info("tb_top", $sformatf("Next item=%s", l_key), UVM_MEDIUM)
        end

          while (l_evt_pool.prev(l_key)) begin        
          `uvm_info("tb_top", $sformatf("Prev item=%s", l_key), UVM_MEDIUM)
        end

        l_evt_pool.last(l_key);
        `uvm_info("tb_top", $sformatf("Last item=%s", l_key), UVM_MEDIUM)          		

    end
endmodule

// This function internally calls get() and if no item exists by 
  // that key, a new item is created with that key and returned.

  static function T get_global (KEY key);
    this_type gpool;
    gpool = get_global_pool(); 
    return gpool.get(key);
  endfunction

if (! l_evt_pool.exists("event_name"))
      `uvm_error("ERR", "event_name does not exist in uvm_event_pool !")
    else
       l_evt = l_evt_pool.get_global("event_name");

interface my_if;
  logic 	rstn;
endinterface

// The agent class monitors the interface and triggers the event "evt_rstn" to
// let any component that is listening to this event to respond. For example,
// a scoreboard can listen to this event and reset its internal states.
class my_agent extends uvm_agent;
  `uvm_component_utils(my_agent)

  virtual my_if  	vif;
  uvm_event_pool 	m_pool;
  uvm_event 		m_evt_rstn;

  function new(string name="my_agent", uvm_component parent=null);
    super.new(name, parent);
  endfunction

  virtual function void build_phase(uvm_phase phase);
    uvm_event_pool 		l_pool;

    super.build_phase(phase);

    if (! uvm_config_db #(virtual my_if)::get(null, "*", "vif", vif))
      `uvm_fatal(get_type_name(), $sformatf("[NOVIF] vif not found !"))

    m_evt_rstn = new();

    l_pool = uvm_event_pool::get_global_pool();
    l_pool.add("evt_rstn", m_evt_rstn);
  endfunction

  virtual task run_phase(uvm_phase phase);
    super.run_phase(phase);    
    fork
      reset_tracker();
    join_none
  endtask

  virtual task reset_tracker();
    `uvm_info (get_type_name(), "[reset_tracker] Start reset monitor", UVM_MEDIUM)
    forever begin
  	  @(negedge vif.rstn);
      m_evt_rstn.trigger();
    end      
  endtask

endclass

// The environment class receives the reset monitor trigger
class my_env extends uvm_env;
  `uvm_component_utils(my_env)

  my_agent 	m_agent;

  function new(string name="my_env", uvm_component parent=null);
    super.new(name, parent);
  endfunction

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);

    m_agent = my_agent::type_id::create("m_agent", this);
  endfunction

  virtual task run_phase(uvm_phase phase);
    super.run_phase(phase);

    fork
      track();
    join_none
  endtask

  virtual task track();
    uvm_event 	l_evt_rstn = uvm_event_pool::get_global("m_evt_rstn");

    if (l_evt_rstn == null)
      `uvm_fatal(get_type_name(), "Did not find m_evt_rstn")
    else
      `uvm_info(get_type_name(), $sformatf("Found item %s", l_evt_rstn.get_name()), UVM_MEDIUM)

    `uvm_info(get_type_name(), "[track] Start tracker", UVM_MEDIUM)
    forever begin
      l_evt_rstn.wait_trigger();
      `uvm_info(get_type_name(), $sformatf("[track] Reset found"), UVM_MEDIUM)
    end
  endtask  
endclass

